LPML.CSS:
#langpedia {
    animation: growrotate 1.5s ease-in-out infinite alternate;
    color: lightblue;
}

@keyframes growrotate {
    from {
        transform: scale(1) rotate(-4deg);
    }
    to {
        transform: scale(1.1) rotate(10deg);
    }
}

body {
    overflow-x: hidden;
}

LPML.JS:
const articles = {{ARTICLES_ARRAY}};
const searchinput = document.getElementById("searchinput");

searchinput.addEventListener('keydown', function(event) {
    if (event.key == "Enter") {
        document.getElementById("results").innerHTML = "Results:\br\";
        var results = articles.filter(a => a.includes(searchinput.value.toLowerCase()));
        for (const article of results) {
            const r = document.createElement("a");
            r.textContent = article;
            r.href = "{{ROOT}}" + article + ".html";
            document.getElementById("results").appendChild(r);
            document.getElementById("results").appendChild(document.createElement("br"));
        }
    }
});
